changeSet.sql:
CREATE FUNCTION touch_user_last_activity() RETURNS trigger AS $$
BEGIN
    UPDATE users SET last_activity_at = now() WHERE id = COALESCE(NEW.user_id, OLD.user_id);
    RETURN COALESCE(NEW, OLD);
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER trg_watch_progress_touch AFTER INSERT OR UPDATE OR DELETE ON watch_progress FOR EACH ROW EXECUTE FUNCTION touch_user_last_activity();
CREATE TRIGGER trg_favourites_touch AFTER INSERT OR UPDATE OR DELETE ON favourites FOR EACH ROW EXECUTE FUNCTION touch_user_last_activity();
CREATE TRIGGER trg_refresh_tokens_touch AFTER INSERT OR UPDATE OR DELETE ON refresh_tokens FOR EACH ROW EXECUTE FUNCTION touch_user_last_activity();

changeSet.rollback:
DROP TRIGGER trg_refresh_tokens_touch ON refresh_tokens;
DROP TRIGGER trg_favourites_touch ON favourites;
DROP TRIGGER trg_watch_progress_touch ON watch_progress;
